)

const (
	pagerEnvVar       = "PAGER"
	lessEnvVar        = "LESS"
	lessPagerName     = "less"
	lessRawControlEnv = "LESS=-R"
	windowsGOOS       = "windows"
	darwinGOOS        = "darwin"
)

var generateTranscriptSummary = summarize.GenerateFromTranscript

// resolveSummaryTimeout picks the effective deadline for `explain --generate`
// using the precedence: per-run flag > settings.summary_timeout_seconds > 0.
// Returns 0 to mean "no deadline" — the caller skips context.WithTimeout
// entirely and the provider call inherits the parent context unchanged.
//
// Settings load failures are logged at debug and fall through to 0;
// a parsing hiccup must not break summary generation.
func resolveSummaryTimeout(ctx context.Context, flagSeconds int) time.Duration {
	if flagSeconds > 0 {
		return time.Duration(flagSeconds) * time.Second
	}
	s, err := settings.Load(ctx)
	if err != nil {
		logging.Debug(ctx, "summary timeout: settings load failed; no deadline",
			slog.String("error", err.Error()))
		return 0
	}
	if v := s.SummaryTimeoutValue(); v > 0 {
		return v
	}
	return 0
}

// errCannotGenerateTemporaryCheckpoint is returned by runExplainCheckpoint when
// --generate is requested for a target that does not match any committed
// checkpoint. runExplainAuto uses errors.Is to detect this case and fall back
// to resolving the target as a git commit ref.
var errCannotGenerateTemporaryCheckpoint = errors.New("cannot generate summary for temporary checkpoint")

type explainCheckpointLookup struct {
	repo      *git.Repository
	store     checkpoint.PersistentStore
	committed []checkpoint.CheckpointInfo
}

func (l *explainCheckpointLookup) Close() error {
	if l == nil || l.repo == nil {
		return nil
	}
	if err := l.repo.Close(); err != nil {
		return fmt.Errorf("close repository: %w", err)
	}
	return nil
}

// generateOrRawLabel returns the user-facing verb for the action the user
// requested, used in error messages when a commit target has no trailer.
func generateOrRawLabel(generate bool) string {
	if generate {
		return "generate summary"
	}
	return "show raw transcript"
}

// printNoTrailerMessage renders the friendly message shown when a resolved
// commit has no Entire-Checkpoint trailer in read-only modes. Takes the
// repo so the hash can be abbreviated to the minimum unique length for
// this repo's object set (matching git's --abbrev behavior).
func printNoTrailerMessage(w io.Writer, repo *git.Repository, hash plumbing.Hash) {
	styles := newStatusStyles(w)
	rows := []explainRow{
		{Label: "commit", Value: abbreviateCommitHash(repo, hash)},
		{Label: "reason", Value: "no Entire-Checkpoint trailer"},
		{Label: "hint", Value: "the commit exists but was not created during an Entire session"},
		{Label: "", Value: "(or its trailer was removed)"},
	}
	fmt.Fprint(w, styles.renderFailure("No associated Entire checkpoint", rows))
}

// errAmbiguousCommitPrefix is returned by resolveCommitUnambiguous when a
// hex prefix matches more than one commit. Callers use errors.Is to detect
// this case and surface the full wrapped message verbatim.
var errAmbiguousCommitPrefix = errors.New("ambiguous commit prefix")

// commitHashesWithPrefix enumerates all commit hashes in the repo whose
// SHA starts with the given hex prefix. Returns nil when the storer is not
// a *filesystem.Storage or the prefix isn't decodable as hex.
//
// Per PR review (discussion_r3113804961): the reviewer specifically
// suggested repo.Storer.(*filesystem.Storage).HashesWithPrefix followed by
// commit filtering. Using this primitive both in resolution (detect
// ambiguous user input) and in display (dynamically abbreviate shown
// hashes to the minimum unique length).
func commitHashesWithPrefix(repo *git.Repository, prefix string) []plumbing.Hash {
	s, ok := repo.Storer.(*filesystem.Storage)
	if !ok {
		return nil
	}
	// Truncate to even length for byte-aligned hex decoding.
	evenHex := prefix[:len(prefix)&^1]
	decoded, err := hex.DecodeString(evenHex)
	if err != nil || len(decoded) == 0 {
		return nil
	}
	candidates, err := s.HashesWithPrefix(decoded)
	if err != nil {
		return nil
	}
	var commits []plumbing.Hash
	for _, h := range candidates {
		// HashesWithPrefix matches on even byte boundaries; filter the
		// dangling nybble for odd-length prefixes.
		if len(evenHex) != len(prefix) && !strings.HasPrefix(h.String(), prefix) {
			continue
		}
		if _, err := repo.CommitObject(h); err != nil {
			continue
		}
		commits = append(commits, h)
	}
	return commits
}

// resolveCommitUnambiguous resolves a ref to a commit hash, returning
// errAmbiguousCommitPrefix (and the matching hashes) when a hex-prefix input
// matches more than one commit. go-git v6's ResolveRevision silently picks
// the first candidate in ambiguous cases (its source explicitly says "for
// speed purposes don't bother to detect the ambiguity"), which could pick
// the wrong commit. Non-hex refs (HEAD, branch names, HEAD~1) bypass the
// ambiguity check via commitHashesWithPrefix returning nil.
//
// The structured ambiguous return lets callers render a styled failure
// block (with each match's timestamp/session) without re-resolving the
// matches themselves.
func resolveCommitUnambiguous(repo *git.Repository, ref string) (plumbing.Hash, []plumbing.Hash, error) {
	hash, err := repo.ResolveRevision(plumbing.Revision(ref))
	if err != nil {
		return plumbing.ZeroHash, nil, err //nolint:wrapcheck // caller contextualizes
	}
	matches := commitHashesWithPrefix(repo, ref)
	if len(matches) <= 1 {
		return *hash, nil, nil
	}
	return plumbing.ZeroHash, matches, errAmbiguousCommitPrefix
}

// abbreviateCommitHash returns the shortest prefix of hash unique among
// commit objects in the repo, matching git's --abbrev-commit auto-growth
// so displayed short SHAs stay unambiguous as the repo grows. Falls back
// to a fixed 12-char prefix if the storer doesn't support fast prefix
// lookup, or to the full hash if somehow never unique.

// Package checkpoint provides types and interfaces for checkpoint storage.
//
// A Checkpoint captures a point-in-time within a session, containing either
// full state (Temporary) or metadata with a commit reference (Committed).
//
// See docs/architecture/sessions-and-checkpoints.md for the full domain model.
package checkpoint

import (
	"context"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"

	"github.com/go-git/go-git/v6/plumbing"
)

// Checkpoint represents a save point within a session.
type Checkpoint struct {
	// ID is the unique checkpoint identifier
	ID string

	// SessionID is the session this checkpoint belongs to
	SessionID string

	// Timestamp is when this checkpoint was created
	Timestamp time.Time

	// Type indicates temporary (full state) or committed (metadata only)
	Type Type

	// Message is a human-readable description of the checkpoint
	Message string
}

// Type indicates the storage location and lifecycle of a checkpoint.
type Type int

const (
	// Ephemeral checkpoints contain full state (code + metadata) and are stored
	// on shadow branches (entire/<commit-hash>). Holds pending intra-session state.
	Ephemeral Type = iota

	// Persistent checkpoints contain metadata + commit reference and are stored
	// on the entire/checkpoints/v1 branch. They are the permanent record.
	Persistent
)

// EphemeralStore provides the production shadow-branch checkpoint surface.
type EphemeralStore interface {
	Write(ctx context.Context, req EphemeralWriteRequest) (WriteEphemeralResult, error)
	Read(ctx context.Context, baseCommit, worktreeID string) (*ReadEphemeralResult, error)
	List(ctx context.Context) ([]EphemeralInfo, error)
	ListCheckpoints(ctx context.Context, baseCommit, worktreeID, sessionID string, limit int) ([]EphemeralCheckpointInfo, error)
	ListCheckpointsForBranch(ctx context.Context, branchName, sessionID string, limit int) ([]EphemeralCheckpointInfo, error)
	ListAllCheckpoints(ctx context.Context, sessionID string, limit int) ([]EphemeralCheckpointInfo, error)
	GetTranscriptFromCommit(ctx context.Context, commitHash plumbing.Hash, metadataDir string, agentType types.AgentType) ([]byte, error)
	ShadowBranchExists(baseCommit, worktreeID string) bool
}

// WriteEphemeralResult contains the result of writing a temporary checkpoint.
type WriteEphemeralResult struct {
	// CommitHash is the hash of the created or existing checkpoint commit
	CommitHash plumbing.Hash

	// Skipped is true if the checkpoint was skipped due to no changes
	// (tree hash matched the previous checkpoint)
	Skipped bool
}

// WriteEphemeralOptions contains options for writing a temporary checkpoint.
type WriteEphemeralOptions struct {
	// SessionID is the session identifier
	SessionID string

	// BaseCommit is the commit hash this session is based on
	BaseCommit string

	// WorktreeID is the internal git worktree identifier (empty for main worktree)
	// Used to create worktree-specific shadow branch names
	WorktreeID string

	// ModifiedFiles are files that have been modified (relative paths)
	ModifiedFiles []string

	// NewFiles are files that have been created (relative paths)
	NewFiles []string

	// DeletedFiles are files that have been deleted (relative paths)
	DeletedFiles []string

	// MetadataDir is the repo-relative path to the metadata directory
	// (.entire/metadata/<session>). It doubles as the git tree path the
	// directory's files land at, and as the name the .entire root reads them
	// through — there is deliberately no absolute counterpart, because two
	// spellings of one directory is how they come to disagree.
	MetadataDir string

	// CommitMessage is the commit subject line
	CommitMessage string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// IsFirstCheckpoint indicates if this is the first checkpoint of the session
	// When true, all working directory files are captured (not just modified)
	IsFirstCheckpoint bool
}

// ReadEphemeralResult contains the result of reading a temporary checkpoint.
type ReadEphemeralResult struct {
	// CommitHash is the hash of the checkpoint commit
	CommitHash plumbing.Hash

	// TreeHash is the hash of the tree containing the checkpoint state
	TreeHash plumbing.Hash

	// SessionID is the session identifier from the commit trailer
	SessionID string

	// MetadataDir is the metadata directory path from the commit trailer
	MetadataDir string

	// Timestamp is when the checkpoint was created
	Timestamp time.Time
}

// EphemeralInfo contains summary information about a shadow branch.
type EphemeralInfo struct {
	// BranchName is the full branch name (e.g., "entire/abc1234")
	BranchName string

	// BaseCommit is the short commit hash this branch is based on
	BaseCommit string

	// LatestCommit is the hash of the latest commit on the branch
	LatestCommit plumbing.Hash

	// SessionID is the session identifier from the latest commit
	SessionID string

	// Timestamp is when the latest checkpoint was created
	Timestamp time.Time
}

// Info provides summary information for listing checkpoints.
// This is the generic checkpoint info type.
type Info struct {
	// ID is the checkpoint identifier
	ID string

	// SessionID identifies the session
	SessionID string

	// Type indicates temporary or committed
	Type Type

	// CreatedAt is when the checkpoint was created
	CreatedAt time.Time

	// Message is a summary description
	Message string
}

// WriteEphemeralTaskOptions contains options for writing a task checkpoint.
// Task checkpoints are created when a subagent completes and contain both
// code changes and task-specific metadata.
type WriteEphemeralTaskOptions struct {
	// SessionID is the session identifier
	SessionID string

	// BaseCommit is the commit hash this session is based on
	BaseCommit string

	// WorktreeID is the internal git worktree identifier (empty for main worktree)
	// Used to create worktree-specific shadow branch names
	WorktreeID string

	// ToolUseID is the unique identifier for this Task tool invocation
	ToolUseID string

	// AgentID is the subagent identifier
	AgentID string

	// Agent identifies the agent that spawned the subagent. Needed to sanitize the
	// stored subagent transcript: the type cannot be recovered from content, since
	// DetectAgentTypeFromContent only recognizes Gemini.
	Agent types.AgentType

	// ModifiedFiles are files that have been modified (relative paths)
	ModifiedFiles []string

	// NewFiles are files that have been created (relative paths)
	NewFiles []string

	// DeletedFiles are files that have been deleted (relative paths)
	DeletedFiles []string

	// TranscriptPath is the path to the main session transcript
	TranscriptPath string

	// SubagentTranscriptPath is the path to the subagent's transcript
	SubagentTranscriptPath string

	// CheckpointUUID is the UUID marking where this checkpoint's transcript slice starts
	CheckpointUUID string

	// CommitMessage is the commit message (already formatted)
	CommitMessage string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// IsIncremental indicates this is an incremental checkpoint
	IsIncremental bool

	// IncrementalSequence is the checkpoint sequence number
	IncrementalSequence int

	// IncrementalType is the tool that triggered this checkpoint
	IncrementalType string

	// IncrementalData is the tool_input payload for this checkpoint
	IncrementalData []byte
}

// EphemeralCheckpointInfo contains information about a single commit on a shadow branch.
// Used by ListCheckpoints to provide pending checkpoint data.
type EphemeralCheckpointInfo struct {
	// CommitHash is the hash of the checkpoint commit
	CommitHash plumbing.Hash

	// Message is the first line of the commit message
	Message string

	// SessionID is the session identifier from the Entire-Session trailer
	SessionID string

	// MetadataDir is the metadata directory path from trailers
	MetadataDir string

	// IsTaskCheckpoint indicates if this is a task checkpoint
	IsTaskCheckpoint bool

	// ToolUseID is the tool use ID for task checkpoints
	ToolUseID string

	// Timestamp is when the checkpoint was created
	Timestamp time.Time
}

